import{c as t,Q as o,j as a,m as r}from"./chunks/framework.BPKcPtvA.js";const g=JSON.parse('{"title":"Before Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/before-getting-started.md","filePath":"getting-started/before-getting-started.md"}'),n={name:"getting-started/before-getting-started.md"};function s(i,e,l,d,h,u){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="before-getting-started" tabindex="-1">Before Getting Started <a class="header-anchor" href="#before-getting-started" aria-label="Permalink to &quot;Before Getting Started&quot;">​</a></h1><h2 id="use-the-documentation" tabindex="-1">Use the Documentation <a class="header-anchor" href="#use-the-documentation" aria-label="Permalink to &quot;Use the Documentation&quot;">​</a></h2><p>All of our themes, like any technical product, come with documentation to follow. Some themes have many features and options for virtually any need. Do not expect to get the most out of these tools without reading the documentation first. Use it and you will be able to create amazing, professional-looking websites.</p><h2 id="server-requirements" tabindex="-1">Server Requirements <a class="header-anchor" href="#server-requirements" aria-label="Permalink to &quot;Server Requirements&quot;">​</a></h2><p>Most issues users experience are related to <a href="./../general/server-requirements.html">Server Requirements</a> not being met. Problems such as demo content import failures, menus not saving, pages not rendering correctly and other oddities are typically caused by excessively low PHP configuration limits on the server.</p><p>Many hosts keep limits low to conserve resources — but you are paying for those resources and should expect your money&#39;s worth. These values are typically lower on <a href="./../general/low-budget-hosts.html">low budget hosts</a>.</p><p>Before starting, right after installing the theme, check your System Status or use the <a href="https://wordpress.org/plugins/wordpress-php-info/" target="_blank" rel="noreferrer">WordPress phpinfo()</a> plugin to verify your server settings. To avoid any trouble, see our list of <a href="./../general/recommended-web-hosts.html">recommended hosts</a>.</p><h2 id="demo-contents" tabindex="-1">Demo Contents <a class="header-anchor" href="#demo-contents" aria-label="Permalink to &quot;Demo Contents&quot;">​</a></h2><p>Once you install the demo content, you will have a replica of the theme demo site. To make your workflow as smooth as possible, we suggest installing the entire demo, selecting the pages you need, and removing the rest. If the theme includes a portfolio, make sure to install the related Portfolio plugin before importing the demo content.</p><h2 id="light-and-dark-skins" tabindex="-1">Light and Dark Skins <a class="header-anchor" href="#light-and-dark-skins" aria-label="Permalink to &quot;Light and Dark Skins&quot;">​</a></h2><p>When using one of our themes, especially those that include a page builder, you will see references to &quot;Light&quot; and &quot;Dark&quot; skins. Skins allow you to switch text color in accordance with your background and design:</p><ul><li><strong>Light skin</strong> — dark text on a bright background, used in bright layouts.</li><li><strong>Dark skin</strong> — bright text on a dark background, used in dark layouts.</li></ul><p>The skin system makes it much easier to create sections featuring contrast.</p><h2 id="theme-settings" tabindex="-1">Theme Settings <a class="header-anchor" href="#theme-settings" aria-label="Permalink to &quot;Theme Settings&quot;">​</a></h2><p>Theme settings are the backbone of our themes. They give you full control over your website and allow you to customize the design without modifying a single line of code. The three major groups of options are:</p><h3 id="customizer-mods" tabindex="-1">Customizer Mods <a class="header-anchor" href="#customizer-mods" aria-label="Permalink to &quot;Customizer Mods&quot;">​</a></h3><p>Responsible for the global appearance of the entire website, unless overridden by Page Options. Accessible via <strong>Appearance &gt; Customizer</strong> in your admin panel, or by clicking &quot;Customize&quot; in the frontend admin bar. Uses the native WordPress customizer with live preview.</p><h3 id="page-options" tabindex="-1">Page Options <a class="header-anchor" href="#page-options" aria-label="Permalink to &quot;Page Options&quot;">​</a></h3><p>Located inside every page, post and product single page. They allow you to override particular Customizer Mods for individual pages — for example, setting a different Page Header per page.</p><h3 id="additional-options" tabindex="-1">Additional Options <a class="header-anchor" href="#additional-options" aria-label="Permalink to &quot;Additional Options&quot;">​</a></h3><p>Complementary to the Customizer mods, found under the <strong>Appearance</strong> menu in the WordPress admin. They typically include the Google Fonts loader, maintenance page settings, and more.</p>',21)])])}const m=t(n,[["render",s]]);export{g as __pageData,m as default};
